import{_ as n,c as i,o as t,ae as r}from"./chunks/framework.CHDT0Kbg.js";const k=JSON.parse('{"title":"Datenschutzerklärung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy-policy.md","filePath":"de/guide/privacy-policy.md","lastUpdated":1795170900000}'),a={name:"de/guide/privacy-policy.md"};function o(s,e,l,d,u,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="datenschutzerklarung" tabindex="-1">Datenschutzerklärung <a class="header-anchor" href="#datenschutzerklarung" aria-label="Permalink to &quot;Datenschutzerklärung&quot;">​</a></h1><p>Was Persim erhebt und was auf deinem Gerät bleibt.</p><h2 id="kein-konto-kein-cloud-profil" tabindex="-1">Kein Konto, kein Cloud-Profil <a class="header-anchor" href="#kein-konto-kein-cloud-profil" aria-label="Permalink to &quot;Kein Konto, kein Cloud-Profil&quot;">​</a></h2><p>Persim verlangt keine Anmeldung und erstellt kein Online-Konto. Verlauf, Lesezeichen, offene Tabs, Downloads und Cookies werden auf deinem Mac gespeichert.</p><h2 id="informationen-zum-anzeigen-von-seiten" tabindex="-1">Informationen zum Anzeigen von Seiten <a class="header-anchor" href="#informationen-zum-anzeigen-von-seiten" aria-label="Permalink to &quot;Informationen zum Anzeigen von Seiten&quot;">​</a></h2><p>Wie jeder Browser sendet Persim die aufgerufenen Adressen an die jeweilige Website. Persim selbst lädt deinen Browserverlauf nicht auf einen Server hoch.</p><h2 id="netzwerkfunktionen-die-du-einschalten-kannst" tabindex="-1">Netzwerkfunktionen, die du einschalten kannst <a class="header-anchor" href="#netzwerkfunktionen-die-du-einschalten-kannst" aria-label="Permalink to &quot;Netzwerkfunktionen, die du einschalten kannst&quot;">​</a></h2><ul><li>Abonnements zur Werbeblockierung aktualisieren ihre Regeln über das Netz. Schlägt die Aktualisierung fehl, wirken die gespeicherten Regeln weiter.</li><li>Userscripts und Dateien werden nur heruntergeladen, wenn du es anforderst.</li><li>Bei der Eingabe in der Adressleiste kommen Vorschläge von deiner gewählten Suchmaschine.</li></ul><h2 id="lokale-berechtigungen" tabindex="-1">Lokale Berechtigungen <a class="header-anchor" href="#lokale-berechtigungen" aria-label="Permalink to &quot;Lokale Berechtigungen&quot;">​</a></h2><p>Kamera, Mikrofon und Dateizugriff werden pro Website gemerkt und lassen sich in den Einstellungen ändern. Standort und Benachrichtigungen verwaltet macOS. Ein privates Fenster (⌘⇧N) hinterlässt keine Spuren in Verlauf und Sitzung.</p><h2 id="websites-dritter" tabindex="-1">Websites Dritter <a class="header-anchor" href="#websites-dritter" aria-label="Permalink to &quot;Websites Dritter&quot;">​</a></h2><p>Die besuchten Websites werden von anderen betrieben und haben eigene Datenschutzregeln. Die integrierten Seiten von Persim verfolgen dich nicht.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Datenschutzfragen: <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>.</p>',14)])])}const g=n(a,[["render",o]]);export{k as __pageData,g as default};
